"""
Codebase seed — Minimal Flask Todo API (tier 1, good seams)

A single-file Flask app with clean structure: models, routes, error handling.
Extended with JWT authentication and per-user task ownership.

The data access layer has been refactored into the Repository pattern. All
SQLite queries live in ``repositories.py``; route handlers only call
repository methods.
"""

import functools
import os
import sqlite3
import time

import jwt
from flask import Flask, g, jsonify, request
from werkzeug.security import check_password_hash

from repositories import TaskRepository, UserRepository
from tasks import send_notification_email

app = Flask(__name__)

DATABASE = os.environ.get("DATABASE", "todos.db")
SECRET_KEY = os.environ.get("SECRET_KEY", "dev-secret-key-change-me-0123456789abcdef")
TOKEN_TTL_SECONDS = 86400


def get_db():
    conn = sqlite3.connect(DATABASE)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    with get_db() as conn:
        conn.execute(
            "CREATE TABLE IF NOT EXISTS users ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  username TEXT NOT NULL UNIQUE,"
            "  password_hash TEXT NOT NULL"
            ")"
        )
        conn.execute(
            "CREATE TABLE IF NOT EXISTS tasks ("
            "  id INTEGER PRIMARY KEY AUTOINCREMENT,"
            "  title TEXT NOT NULL,"
            "  status TEXT NOT NULL DEFAULT 'pending',"
            "  created_at TEXT NOT NULL,"
            "  owner_id INTEGER"
            ")"
        )
        # Migration: add owner_id to pre-existing tasks tables without data loss.
        columns = [row[1] for row in conn.execute("PRAGMA table_info(tasks)").fetchall()]
        if "owner_id" not in columns:
            conn.execute("ALTER TABLE tasks ADD COLUMN owner_id INTEGER")
        conn.commit()


user_repo = UserRepository(get_db)
task_repo = TaskRepository(get_db)


# ── Auth helpers ──────────────────────────────────────────────

def generate_token(user_id: int) -> str:
    payload = {"user_id": user_id, "exp": int(time.time()) + TOKEN_TTL_SECONDS}
    return jwt.encode(payload, SECRET_KEY, algorithm="HS256")


def decode_token(token: str):
    try:
        payload = jwt.decode(token, SECRET_KEY, algorithms=["HS256"])
        return payload.get("user_id")
    except (jwt.ExpiredSignatureError, jwt.InvalidTokenError):
        return None


def require_auth(f):
    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        auth = request.headers.get("Authorization", "")
        if not auth.startswith("Bearer "):
            return jsonify({"error": "missing or invalid token"}), 401
        token = auth.split(" ", 1)[1]
        user_id = decode_token(token)
        if user_id is None or user_repo.get_by_id(user_id) is None:
            return jsonify({"error": "missing or invalid token"}), 401
        g.current_user_id = user_id
        return f(*args, **kwargs)

    return wrapper


# ── Helpers ───────────────────────────────────────────────────

def get_user_email(user: dict) -> str:
    return f"{user['username']}@example.com"


# ── Auth routes ───────────────────────────────────────────────

@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = (data.get("username") or "").strip()
    password = data.get("password") or ""
    if not username or not password:
        return jsonify({"error": "username and password are required"}), 400
    user = user_repo.create(username, password)
    if user is None:
        return jsonify({"error": "username already exists"}), 409
    return jsonify(user), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = (data.get("username") or "").strip()
    password = data.get("password") or ""
    user = user_repo.get_by_username(username)
    if user is None or not check_password_hash(user["password_hash"], password):
        return jsonify({"error": "invalid username or password"}), 401
    return jsonify({"token": generate_token(user["id"])})


# ── Task routes ───────────────────────────────────────────────

@app.route("/tasks", methods=["GET"])
@require_auth
def list_tasks():
    return jsonify(task_repo.get_all(g.current_user_id))


@app.route("/tasks", methods=["POST"])
@require_auth
def add_task():
    data = request.get_json(silent=True) or {}
    title = data.get("title", "").strip()
    if not title:
        return jsonify({"error": "title is required"}), 400
    task = task_repo.create(title, g.current_user_id)
    return jsonify(task), 201


@app.route("/tasks/<int:task_id>", methods=["GET"])
@require_auth
def show_task(task_id: int):
    task = task_repo.get_by_id(task_id, g.current_user_id)
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task)


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@require_auth
def edit_task(task_id: int):
    data = request.get_json(silent=True) or {}
    old_task = task_repo.get_by_id(task_id, g.current_user_id)
    task = task_repo.update(
        task_id,
        g.current_user_id,
        title=data.get("title"),
        status=data.get("status"),
    )
    if task is None:
        return jsonify({"error": "task not found"}), 404
    if task["status"] == "completed" and old_task["status"] != "completed":
        owner = user_repo.get_by_id(g.current_user_id)
        send_notification_email.delay(get_user_email(owner), task["title"])
    return jsonify(task)


if __name__ == "__main__":
    init_db()
    app.run(debug=True)

"""
Repository pattern data access layer for the todo API.

All SQLite queries live here. Route handlers in ``app.py`` must go through
these repositories instead of touching the database directly.
"""

import sqlite3
from abc import ABC, abstractmethod
from datetime import datetime

from werkzeug.security import generate_password_hash


class BaseRepository(ABC):
    """Abstract base repository providing common CRUD operations."""

    def __init__(self, get_db):
        self._get_db = get_db

    def _connect(self):
        return self._get_db()

    @abstractmethod
    def create(self, *args, **kwargs):
        """Insert a new entity and return it."""

    @abstractmethod
    def get_all(self, *args, **kwargs):
        """Return all entities."""

    @abstractmethod
    def get_by_id(self, entity_id, *args, **kwargs):
        """Return a single entity by id, or None if not found."""

    @abstractmethod
    def update(self, entity_id, *args, **kwargs):
        """Update an entity and return the updated entity, or None."""

    @abstractmethod
    def delete(self, entity_id, *args, **kwargs):
        """Delete an entity."""


class UserRepository(BaseRepository):
    """Data access for the ``users`` table."""

    def create(self, username, password):
        with self._connect() as conn:
            try:
                cursor = conn.execute(
                    "INSERT INTO users (username, password_hash) VALUES (?, ?)",
                    (username, generate_password_hash(password)),
                )
                conn.commit()
                return {"id": cursor.lastrowid, "username": username}
            except sqlite3.IntegrityError:
                return None

    def get_all(self):
        with self._connect() as conn:
            rows = conn.execute("SELECT * FROM users").fetchall()
            return [dict(row) for row in rows]

    def get_by_id(self, entity_id):
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM users WHERE id = ?", (entity_id,)
            ).fetchone()
            return dict(row) if row else None

    def get_by_username(self, username):
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM users WHERE username = ?", (username,)
            ).fetchone()
            return dict(row) if row else None

    def update(self, entity_id, **kwargs):
        with self._connect() as conn:
            updates = []
            params = []
            for column, value in kwargs.items():
                updates.append(f"{column} = ?")
                params.append(value)
            if updates:
                params.append(entity_id)
                conn.execute(
                    f"UPDATE users SET {', '.join(updates)} WHERE id = ?", params
                )
                conn.commit()
        return self.get_by_id(entity_id)

    def delete(self, entity_id):
        with self._connect() as conn:
            conn.execute("DELETE FROM users WHERE id = ?", (entity_id,))
            conn.commit()


class TaskRepository(BaseRepository):
    """Data access for the ``tasks`` table."""

    def create(self, title, owner_id):
        with self._connect() as conn:
            now = datetime.utcnow().isoformat()
            cursor = conn.execute(
                "INSERT INTO tasks (title, status, created_at, owner_id)"
                " VALUES (?, 'pending', ?, ?)",
                (title, now, owner_id),
            )
            conn.commit()
            return {
                "id": cursor.lastrowid,
                "title": title,
                "status": "pending",
                "created_at": now,
                "owner_id": owner_id,
            }

    def get_all(self, owner_id):
        with self._connect() as conn:
            rows = conn.execute(
                "SELECT * FROM tasks WHERE owner_id = ? ORDER BY created_at DESC",
                (owner_id,),
            ).fetchall()
            return [dict(row) for row in rows]

    def get_by_id(self, entity_id, owner_id):
        with self._connect() as conn:
            row = conn.execute(
                "SELECT * FROM tasks WHERE id = ? AND owner_id = ?",
                (entity_id, owner_id),
            ).fetchone()
            return dict(row) if row else None

    def update(self, entity_id, owner_id, title=None, status=None):
        task = self.get_by_id(entity_id, owner_id)
        if task is None:
            return None
        with self._connect() as conn:
            updates = []
            params = []
            if title is not None:
                updates.append("title = ?")
                params.append(title)
            if status is not None:
                updates.append("status = ?")
                params.append(status)
            if updates:
                params.append(entity_id)
                params.append(owner_id)
                conn.execute(
                    f"UPDATE tasks SET {', '.join(updates)} WHERE id = ? AND owner_id = ?",
                    params,
                )
                conn.commit()
        return self.get_by_id(entity_id, owner_id)

    def delete(self, entity_id, owner_id=None):
        with self._connect() as conn:
            if owner_id is None:
                conn.execute("DELETE FROM tasks WHERE id = ?", (entity_id,))
            else:
                conn.execute(
                    "DELETE FROM tasks WHERE id = ? AND owner_id = ?",
                    (entity_id, owner_id),
                )
            conn.commit()

